import json, os
needle=['Mousa al-Omar','Mousa al Omar','Musa al-Omar','Moussa al-Omar','موسى العمر']
for root,ds,fs in os.walk('articles'):
 for fn in fs:
  if not fn.endswith('.jsonl'): continue
  p=os.path.join(root,fn)
  with open(p,encoding='utf-8',errors='ignore') as f:
   for line in f:
    if any(x.lower() in line.lower() for x in needle):
     try:
      a=json.loads(line); print(a.get('date_publish'),a.get('title'),a.get('url')); print(a.get('content','')[:3000])
     except: pass
PY"

